package sg.edu.nus.shoopingcart.model;
//Author: Ong Xin Min
public enum PaymentMethod {
    VISA("VISA", "https://sg-media.apjonlinecdn.com/wysiwyg/icon/visa.gif"),
    MASTERCARD("MASTERCARD", "https://sg-media.apjonlinecdn.com/wysiwyg/icon/master.gif"),
    PAYPAL("PAYPAL", "https://www.paypalobjects.com/webstatic/mktg/logo/pp_cc_mark_37x23.jpg"),
    GOOGLE_PAY("GOOGLE PAY", "https://sg-media.apjonlinecdn.com/wysiwyg/icon/google-pay-footer.png"),
    APPLE_PAY("APPLE PAY", "https://sg-media.apjonlinecdn.com/wysiwyg/icon/apple-pay-footer.png"),
    BANK_TRANSFER("BANK TRANSFER", "https://sg-media.apjonlinecdn.com/wysiwyg/wysiwyg/icon/bank_transfer_icon.gif"),
    PAYNOW("PAYNOW", "https://sg-media.apjonlinecdn.com/wysiwyg/wysiwyg/icon/pay_now.jpg"),
    GRABPAY("GRABPAY", "https://sg-media.apjonlinecdn.com/wysiwyg/icon/payment_icons_grabpay.svg"),
    ALIPAY("ALIPAY", "data:image/png;base64,");

    //visa, mastercard, paynow, grabpay, alipay cannot complete purchase - has the error of: java.sql.SQLException: Data truncated for column 'payment_method' at row 1
    private final String displayName;

    private String imageUrl; //URL for the payment method image

    PaymentMethod(String displayName, String imageUrl) {
        this.displayName = displayName;
        this.imageUrl = imageUrl;
    }

    public String getDisplayName() {
        return displayName;
    }

    public String getImageUrl() {
        return imageUrl;
    }

    public void setImageUrl(String imageUrl) {
        this.imageUrl = imageUrl;
    }
}
